/// Renders `message`; one naming no entity, whose text the SDK's
/// sources give, must render with no warning.
fn renders<M: TypedMessage>(intl: &Intl, message: &M, clean: bool) {
    let rendered = intl.render_typed(message);
    if clean {
        assert!(
            rendered.warnings.is_empty(),
            "{}: {:?}",
            M::KEY,
            rendered.warnings
        );
    }
    assert!(!rendered.text.is_empty(), "{}", M::KEY);
}

